mapper.select:
SELECT session_id, runtime_kind, local_client_instance_id
FROM sessions
WHERE session_id = #{sessionId}

mapper.update:
UPDATE sessions
SET runtime_kind = #{runtimeKind},
    local_client_instance_id = #{localClientInstanceId}
WHERE session_id = #{sessionId}

UPDATE sessions
SET local_client_instance_id = #{replacementClientInstanceId}
WHERE workspace_id = #{workspaceId}
  AND runtime_kind = 'LOCAL_CLIENT'
  AND local_client_instance_id = #{expectedClientInstanceId}
